mapper.select:

v.del_flag='0'
  and v.activity_id=#{activityId}
  and v.venue_name like concat('%',#{venueName},'%')
  and v.is_live=#{isLive}

order by v.sort_order asc, v.venue_id asc

mapper.update:
update yc_venue
venue_name=#{venueName}, is_live=#{isLive}, cover_url=#{coverUrl}, live_start=#{liveStart}, live_end=#{liveEnd}, live_status=#{liveStatus}, sort_order=#{sortOrder}, update_by=#{updateBy}, remark=#{remark}, update_time=sysdate()
where venue_id=#{venueId}
